def test_certificate_conditions_refuse_without_other_failed_checks(self) -> None:
    cases = (
        (ExactLinearProgram((1, 1), ((1, 1),), (3,)), LinearProgramCertificate("optimal", (-1, 4), (1,))),
        (ExactLinearProgram((1, 2), ((1, 1),), (3,)), LinearProgramCertificate("optimal", (0, 3), (2,))),
        (ExactLinearProgram((-1, 0), ((1, 1),), (1,)), LinearProgramCertificate("unbounded", primal=(1, 0), ray=(1, 0))),
    )
    for program, certificate in cases:
        refused = program.verify(certificate)
        self.assertEqual(refused.error.kind if refused.error else None, "check")

def test_primal_norm_budget_is_not_masked_by_dual_overflow(self) -> None:
    complex_, omega, zero, _ = bell_witness()
    omega[(0, 1)] = (Q(2**4095), Q(2**4095))
    dual = {edge: (Q(0), Q(0)) for edge in complex_.edges}
    refused = complex_.quotient_value(omega, zero, dual)
    self.assertEqual(refused.error.kind if refused.error else None, "resource")
